def feasible_prefix(n, m, d, a, x):
    last = [-1] * (m + 1)
    for i in range(x):
        if d[i] > 0:
            last[d[i]] = i
    for s in range(1, m + 1):
        if last[s] == -1:
            return False
    need = [0] * x
    for s in range(1, m + 1):
        need[last[s]] = a[s - 1]
    prep = 0
    for i in range(x):
        if need[i] > 0:
            if prep < need[i]:
                return False
            prep -= need[i]
        else:
            prep += 1
    return True

