def oracle(input):
    s = input[0]
    k = input[1]
    MOD = 1000000007

    def steps_to_one(x):
        c = 0
        while x != 1:
            x = bin(x).count('1')
            c += 1
        return c

    if k == 0:
        return 1 if s == '1' else 0

    L = len(s)
    maxm = L
    need = []
    for m in range(maxm + 1):
        if m >= 1 and steps_to_one(m) == k - 1:
            need.append(m)

    if not need:
        return 0

    C = []
    for n in range(L + 1):
        row = [0] * (n + 1)
        row[0] = 1
        row[n] = 1
        j = 1
        while j < n:
            row[j] = (C[n - 1][j - 1] + C[n - 1][j]) % MOD
            j += 1
        C.append(row)

    def count_leq_with_ones(t):
        if t < 0 or t > L:
            return 0
        ans = 0
        ones_used = 0
        i = 0
        while i < L:
            if s[i] == '1':
                rem = L - i - 1
                need_ones = t - ones_used
                if 0 <= need_ones <= rem:
                    ans = (ans + C[rem][need_ones]) % MOD
                ones_used += 1
                if ones_used > t:
                    return ans
            i += 1
        if ones_used == t:
            ans = (ans + 1) % MOD
        return ans

    ans = 0
    i = 0
    while i < len(need):
        m = need[i]
        ans = (ans + count_leq_with_ones(m)) % MOD
        i += 1

    if k == 1:
        ans = (ans - 1) % MOD

    return ans % MOD
